1	/**
2	 * Governed Generate SDK — Full Inline Governance Enforcement
3	 * 
4	 * This is the canonical entry point for any LLM generation that must pass
5	 * through Gravito governance. It wraps the full pipeline:
6	 * 
7	 *   1. Auto-register the calling product (if external)
8	 *   2. Pre-generation: classify content, inject governance context
9	 *   3. LLM generation via safeLLM (never-throw wrapper)
10	 *   4. Post-generation: heuristic analysis → Gravito inline review → decision
11	 *   5. Verdict enforcement: pass / stabilize / block / regenerate
12	 *   6. Failsafe: if Gravito is down, use degraded-mode policy engine
13	 * 
14	 * Usage:
15	 *   const result = await governedGenerate({
16	 *     messages: [{ role: 'user', content: 'Write a health disclaimer' }],
17	 *     productId: 'troubadour-music-app',
18	 *     contentType: 'medical',
19	 *     contentRole: 'user-facing',
20	 *   });
21	 */
22	import { safeLLM, isFallbackResponse } from './safe-llm';
23	import { coProcessorPreGenerate, coProcessorPostGenerate, applyVerdict, type ContentDomain, type CoProcessorVerdict, type CoProcessorDecision } from './co-processor/index';
24	import { registerSurfaceIfMissing, incrementActivityCounter } from './auto-surface-registration';
25	import { evaluateDegradedPolicy, recordDegradedEvaluation } from './degraded-policy-engine';
26	import { resolveGovernanceContext, buildGovernanceInjection, recordContextResolution } from './product-context';
27	import { createLogger } from '../_core/logger';
28	import { getGovernanceBypassState, withGovernanceBypassAsync, type InvokeParams, type InvokeResult, type Message } from '../_core/llm';
29	import { preShapePrompt, enforce, enforceDegraded, recordGeometryEnforcement } from './geometry-controller';
30	import { composeDeepGeometryVerdict, type DeepGeometryVerdict } from './geometry-deep-verdict';
31	import { decideGeometryInfluence } from './geometry-verdict-influence';
32	import { decideManifoldInfluence } from './manifold-verdict-influence';
33	import { getManifoldSessionTrajectory } from '../emotional-geometry-runtime/geometry/manifold-session-state';
34	import { decideRecallInfluence } from './recall-verdict-influence';
35	import { isFeatureEnabled } from '../emotional-geometry-runtime/feature-flags';
36	import { attachCanonicalReceiptIfEnabled, type CanonicalVerdictReceipt } from './canonical-verdict-receipt';
37	import { selectShadowContent, classifyEnforcementOutcome } from './geometry-content-select';
38	import { recordGeometryShadow } from './geometry-shadow-record';
39	import { recordGeometryEvalCapture } from './geometry-eval-capture-record';
40	import { recognizeRepeatFailure, lookupRepeatFailure, type RepeatFailureRecognitionInput } from './repeat-failure-recognition';
41	import { recordDegradedCause } from './degraded-cause-record';
42	import { requestApproval, REGULATED_SURFACES, FAIL_CLOSED_ERROR } from './regulated-surface-preapproval';
43	import { createHash } from 'crypto';
