45	import { preGenerationHook, postGenerationHook, type GeometryPreGenerationResult, type GeometryPostGenerationResult } from '../emotional-geometry-runtime/geometry-runtime-bridge';
46	import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
47	import { createInitialState, updateBaseDimensions, type CanonicalEmotionalState } from '../emotional-geometry-runtime/state/EmotionalState';
48	import { persistGeometryData } from '../emotional-geometry-runtime/session-persistence';
49	import { evaluateAlerts } from '../emotional-geometry-runtime/geometry-alerting';
