51	const log = createLogger('governance');
52	
53	// ============================================================================
54	// TYPES
55	// ============================================================================
56	
57	export interface GovernedGenerateParams {
58	  /** LLM messages (system + user + assistant history) */
59	  messages: InvokeParams['messages'];
60	  /** Model override (optional — uses default if not specified) */
61	  model?: string;
62	  /** Content type for governance classification */
63	  contentType?: string;
64	  /** Content role: user-facing, internal, admin, system */
65	  contentRole?: 'user-facing' | 'internal' | 'admin' | 'system';
66	  /** Product ID for auto-registration and per-product governance */
67	  productId?: string;
68	  /** Product name (used for auto-registration) */
69	  productName?: string;
70	  /** Surface ID for governance context routing */
71	  surfaceId?: string;
72	  /** Audience type for tone calibration */
73	  audienceType?: 'general' | 'professional' | 'technical' | 'legal' | 'medical';
74	  /** System prompt override (prepended to messages) */
75	  systemPrompt?: string;
76	  /** Skip stabilization (useful for creative content) */
77	  skipStabilization?: boolean;
78	  /** Max retries on regenerate verdict (default: 1) */
79	  maxRetries?: number;
80	  /** LLM parameters passthrough */
81	  temperature?: number;
82	  max_tokens?: number;
83	  response_format?: InvokeParams['response_format'];
84	  tools?: InvokeParams['tools'];
85	  tool_choice?: InvokeParams['tool_choice'];
86	  /**
87	   * FAIL-CLOSED geometry-eval capture eligibility. Default (undefined) → NOT
88	   * eligible → no capture row is written even when GEOMETRY_EVAL_CAPTURE_ENABLED
89	   * is on. Only an explicitly-marked internal caller opts in; externally-reachable
90	   * / unscoped callers (e.g. the customer-facing MCP bridge) are skipped by
91	   * construction. Not flipped for any caller in this packet.
92	   */
93	  captureEligible?: boolean;
94	  /**
95	   * FAIL-CLOSED excerpt eligibility. Default (undefined) → the ≤160-char free-text
96	   * excerpt is withheld (structured capture fields are still retained). Stays off
97	   * until a caller is classified safe-for-excerpt, because the regex suppressor is
98	   * not a privacy boundary for non-shape PII/PHI.
99	   */
100	  excerptEligible?: boolean;
101	  /**
102	   * Authenticated tenant, populated ONLY by a caller that resolved it from a
103	   * validated inference credential (resolveInferenceTenant → org-<id>/user-<id>).
104	   * No current caller sets this (see packet trace); untrusted callers MUST leave
105	   * it undefined. It is the ONLY input that can raise the canonical receipt to
106	   * `authenticated_tenant` (a trusted `source`, e.g. 'inference_auth').
107	   */
108	  authenticatedTenant?: { tenantId: string; source: string };
109	}
110	
111	export interface GovernedGenerateResult {
112	  /** Final content after governance */
113	  content: string;
114	  /** Whether governance was applied */
115	  governed: boolean;
116	  /** Governance decision: pass, stabilize, block, regenerate */
117	  decision: string;
118	  /** Whether content was modified by governance */
119	  modified: boolean;
120	  /** Gravito run ID for audit trail */
121	  gravito_run_id?: string;
122	  /** Governance score (0-100) */
123	  score: number;
124	  /** Issues found during governance */
125	  issues: Array<{ type: string; severity: string; description: string }>;
126	  /** Audit trail for debugging */
127	  auditTrail: string[];
128	  /** Processing time in ms */
129	  processingTimeMs: number;
130	  /** Whether failsafe/degraded mode was used */
131	  degradedMode: boolean;
132	  /** Raw LLM result (for advanced consumers) */
133	  rawResult?: InvokeResult;
134	  /** Product registration status */
135	  productRegistered: boolean;
136	  /**
137	   * Canonical verdict receipt (Gate→Remember→Compound→Earn-Authority). Present
138	   * only when CANONICAL_VERDICT_RECEIPT_ENABLED; default-OFF ⇒ absent
139	   * (byte-identical).
140	   */
141	  canonical_receipt?: CanonicalVerdictReceipt;
142	}
143	
144	// ============================================================================
145	// METRICS
146	// ============================================================================
147	
148	interface GovernedGenerateMetrics {
149	  totalCalls: number;
150	  totalPassed: number;
151	  totalStabilized: number;
152	  totalBlocked: number;
153	  totalRegenerated: number;
154	  totalDegraded: number;
155	  totalErrors: number;
156	  avgLatencyMs: number;
157	  byProduct: Record<string, { calls: number; blocked: number; degraded: number }>;
158	}
159	
160	const _metrics: GovernedGenerateMetrics = {
161	  totalCalls: 0,
162	  totalPassed: 0,
163	  totalStabilized: 0,
164	  totalBlocked: 0,
165	  totalRegenerated: 0,
166	  totalDegraded: 0,
167	  totalErrors: 0,
168	  avgLatencyMs: 0,
169	  byProduct: {},
170	};
171	
172	export function getGovernedGenerateMetrics(): GovernedGenerateMetrics {
173	  return { ..._metrics };
174	}
175	
176	// ============================================================================
177	// GEOMETRY→VERDICT INFLUENCE COUNTER (packet gravito_behavior_wiring_proof_a)
178	// Monotonic in-memory counter of geometry-driven verdict ESCALATIONS to block.
179	// Only ever increments when GEOMETRY_VERDICT_INFLUENCE_ENABLED is ON and a
180	// content-driven deep geometry block escalates the live verdict. Mirrors the
181	// review-health counter style (private state + read-only getter + test reset).
182	// ============================================================================
183	
184	let _geometryInfluenceEscalationCount = 0;
185	
186	/** Read-only count of geometry→verdict escalations since boot. */
187	export function getGeometryInfluenceEscalationCount(): number {
188	  return _geometryInfluenceEscalationCount;
189	}
190	
191	/** Reset the geometry→verdict escalation counter (for testing). */
192	export function resetGeometryInfluenceEscalationCount(): void {
193	  _geometryInfluenceEscalationCount = 0;
194	}
195	
196	/**
197	 * WIRED SEAM (default-OFF, escalate-only) — reconcile the live co-processor
198	 * verdict with the DEEP geometry shadow verdict.
199	 *
200	 * Behind GEOMETRY_VERDICT_INFLUENCE_ENABLED: when a CONTENT-driven deep geometry
201	 * `block` is present and the live verdict is not already `block`, escalate the
202	 * response to `block` using the SAME safe-fallback producer applyVerdict uses
203	 * (co-processor/index.ts:416) — so the block message never diverges from the
204	 * canonical block path. Escalate-only: it can only make the gate STRICTER.
205	 *
206	 * FLAG-OFF ⇒ byte-identical to today: zero new work runs and the baseline
207	 * {content, decision, modified} is returned unchanged. NEVER throws into the
208	 * response path — on any error it returns the unmodified baseline plus an audit
209	 * note. The counter is incremented ONLY on a real escalation.
210	 */
211	export function applyGeometryInfluence(
212	  llmResult: InvokeResult,
213	  verdict: CoProcessorVerdict,
214	  deepGeoResult: DeepGeometryVerdict,
215	  currentContent: string,
216	  auditTrail: string[],
217	): { content: string; decision: CoProcessorDecision; modified: boolean } {
218	  const baseline = {
219	    content: currentContent,
220	    decision: verdict.decision,
221	    modified: verdict.wasModified,
222	  };
223	
224	  // FLAG GATE: OFF ⇒ zero new work, byte-identical baseline.
225	  if (!isFeatureEnabled('GEOMETRY_VERDICT_INFLUENCE_ENABLED')) {
226	    return baseline;
227	  }
228	
229	  try {
230	    const influence = decideGeometryInfluence(verdict.decision, deepGeoResult);
231	    if (!influence.escalate) {
232	      return baseline;
233	    }
234	
235	    // Reuse the canonical safe-fallback producer (applyVerdict block branch) so
236	    // the withheld content is identical to a native co-processor block.
237	    const blockedResult = applyVerdict(llmResult, { ...verdict, decision: 'block' });
238	    _geometryInfluenceEscalationCount++;
239	    auditTrail.push(
240	      `[GEOMETRY-INFLUENCE] Escalated ${verdict.decision} → block on: ${influence.triggeringSignals.join(', ')}`,
241	    );
242	    return {
243	      content: extractContent(blockedResult),
244	      decision: 'block',
245	      modified: true,
246	    };
247	  } catch (influenceErr) {
248	    // Defensive: the influence path must NEVER throw into the response path.
249	    auditTrail.push(
250	      `[GEOMETRY-INFLUENCE] Skipped (non-blocking error): ${influenceErr instanceof Error ? influenceErr.message : String(influenceErr)}`,
251	    );
252	    return baseline;
253	  }
254	}
255	
256	// ============================================================================
257	// RECALL→VERDICT INFLUENCE COUNTER (packet gravito_recall_wiring_proof_a)
258	// Monotonic in-memory counter of recall-driven verdict ESCALATIONS to block.
259	// Only ever increments when GEOMETRY_RECALL_INFLUENCE_ENABLED is ON and a
260	// recognized prior persisted FAILING verdict escalates the live verdict. Mirrors
261	// the geometry-influence counter (private state + read-only getter + test reset).
262	// ============================================================================
