359	/**
360	 * WIRED SEAM (default-OFF, escalate-only) — reconcile the live (already
361	 * content/recall-influenced) verdict with the MANIFOLD attractor class of the
362	 * accumulated per-session state trajectory. The final link of the
363	 * score → remember → recall → PREVENT spine wired for the deep-math signal.
364	 *
365	 * Behind MANIFOLD_VERDICT_INFLUENCE_ENABLED: read the in-memory accumulated
366	 * trajectory for this session (getManifoldSessionTrajectory — the default-OFF
367	 * accumulator from manifold_session_state_prereq_a), classify it with the
368	 * corrected Jacobian estimator, and when it is a NON-DEGENERATE, UNSTABLE
369	 * attractor (saddle-point / unstable-node / unstable-spiral) and the current
370	 * verdict is not already `block`, ESCALATE to `block` via the SAME safe-fallback
371	 * producer applyVerdict uses (co-processor/index.ts:416). Escalate-only: it can
372	 * only make the gate STRICTER. Degenerate/empty/too-short trajectories never
373	 * escalate (a constant trajectory is spuriously `saddle-point` and is gated out
374	 * in decideManifoldInfluence BEFORE classification).
375	 *
376	 * FLAG-OFF ⇒ byte-identical to today: zero new work runs (NO trajectory read) and
377	 * the chained-in `current` {content, decision, modified} is returned unchanged.
378	 * NEVER throws into the response path — on any error it returns the unmodified
379	 * `current` plus an audit note. The counter increments ONLY on a real escalation.
380	 */
381	export function applyManifoldInfluence(
382	  llmResult: InvokeResult,
383	  verdict: CoProcessorVerdict,
384	  current: { content: string; decision: CoProcessorDecision; modified: boolean },
385	  ctx: { sessionId: string | null },
386	  auditTrail: string[],
387	): { content: string; decision: CoProcessorDecision; modified: boolean } {
388	  // FLAG GATE: OFF ⇒ zero new work (no trajectory read), byte-identical `current`.
389	  if (!isFeatureEnabled('MANIFOLD_VERDICT_INFLUENCE_ENABLED')) {
390	    return current;
391	  }
392	
393	  try {
394	    // Fail-closed: no session ⇒ no trajectory ⇒ no escalation.
395	    if (!ctx.sessionId) {
396	      return current;
397	    }
398	    const trajectory = getManifoldSessionTrajectory(ctx.sessionId);
399	    const influence = decideManifoldInfluence(current.decision, trajectory);
400	    if (!influence.escalate) {
401	      return current;
402	    }
403	
404	    // Reuse the canonical safe-fallback producer (applyVerdict block branch) so
405	    // the withheld content is identical to a native co-processor block.
406	    const blockedResult = applyVerdict(llmResult, { ...verdict, decision: 'block' });
407	    _manifoldInfluenceEscalationCount++;
408	    auditTrail.push(
409	      `[MANIFOLD-INFLUENCE] Escalated ${current.decision} → block on unstable manifold: ` +
410	        `${influence.manifoldClass} (trajectory=${influence.trajectoryLength}, flag=MANIFOLD_VERDICT_INFLUENCE_ENABLED)`,
411	    );
412	    return {
413	      content: extractContent(blockedResult),
414	      decision: 'block',
415	      modified: true,
416	    };
417	  } catch (influenceErr) {
418	    // Defensive: the manifold-influence path must NEVER throw into the response path.
419	    auditTrail.push(
420	      `[MANIFOLD-INFLUENCE] Skipped (non-blocking error): ${influenceErr instanceof Error ? influenceErr.message : String(influenceErr)}`,
421	    );
422	    return current;
423	  }
424	}
