434	  // prevention layer calls governedGenerate for its AI-based evaluation, so an
435	  // unguarded pipeline recurses infinitely (governedGenerate → co-processor
436	  // post-generation → prevention layer → governedGenerate → …). Step 6 below
437	  // runs the co-processor inside the LLM governance-bypass context (the same
438	  // AsyncLocalStorage mechanism invokeLLM uses for recursion prevention), so a
439	  // governedGenerate call arriving INSIDE that context is by definition part of
440	  // an internal governance evaluation — serve it with a single ungoverned
441	  // safeLLM call instead of re-governing governance's own plumbing.
442	  if (getGovernanceBypassState().bypassed) {
443	    return generateInternalBypass(params);
444	  }
445	
446	  const startTime = Date.now();
447	  const auditTrail: string[] = [];
448	  const maxRetries = params.maxRetries ?? 1;
449	  let degradedMode = false;
450	  let productRegistered = false;
451	
452	  _metrics.totalCalls++;
453	
454	  // Step 1: Auto-register product (non-blocking on failure)
455	  if (params.productId) {
456	    try {
457	      await registerSurfaceIfMissing({
458	        productId: params.productId,
459	        productName: params.productName,
460	        registrationSource: 'governance_request',
461	      });
462	      productRegistered = true;
463	      auditTrail.push(`[REGISTER] Product ${params.productId} registered/cached`);
464	    } catch (err) {
465	      auditTrail.push(`[REGISTER] Failed (non-blocking): ${err}`);
466	    }
467	  }
468	
469	  // Track per-product metrics
470	  const productKey = params.productId || 'internal';
471	  if (!_metrics.byProduct[productKey]) {
472	    _metrics.byProduct[productKey] = { calls: 0, blocked: 0, degraded: 0 };
473	  }
474	  _metrics.byProduct[productKey].calls++;
475	
476	  // Step 2: Resolve product-aware governance context
477	  const govContext = resolveGovernanceContext({
478	    productId: params.productId,
479	    surfaceId: params.surfaceId,
480	    contentRole: params.contentRole,
481	    contentType: params.contentType,
