483	  });
484	  recordContextResolution(govContext);
485	  auditTrail.push(`[CONTEXT] Profile: ${govContext.profile.id}, strictness: ${govContext.profile.strictness}, overrides: [${govContext.overridesApplied.join(', ')}]`);
486	
487	  // Step 2.5: Control Plane Enforcement Gate
488	  // AUTHORITATIVE: Control plane is THE gate — not a suggestion layer
489	  const { enforce: cpEnforce, getEnforcementMode } = await import('../control-plane');
490	  // IDENTITY STAMP (identity only — never content, never prompts): the audit
491	  // rows this gate writes must name their caller so ledger readers can
492	  // attribute entries without log archaeology. surfaceType/callerId are read
493	  // through a widened view — GovernedGenerateParams does not declare them, but
494	  // runtime callers may pass them.
