605	            governed: false,
606	            decision: 'error',
607	            modified: false,
608	            score: 0,
609	            issues: [{ type: 'system_error', severity: 'critical', description: `Governance pipeline failed: ${degradedErr}` }],
610	            auditTrail,
611	            processingTimeMs: Date.now() - startTime,
