622	    content: '',
623	    governed: false,
624	    decision: 'error',
625	    modified: false,
626	    score: 0,
627	    issues: [],
628	    auditTrail,
629	    processingTimeMs: Date.now() - startTime,
630	    degradedMode: true,
631	    productRegistered,
632	  };
633	}
