817	      if (alertsFired > 0) {
818	        auditTrail.push(`[GEOMETRY-ALERTS] ${alertsFired} alert(s) fired`);
819	      }
820	    } catch (alertErr) {
821	      auditTrail.push(`[GEOMETRY-ALERTS] Failed (non-blocking): ${alertErr instanceof Error ? alertErr.message : String(alertErr)}`);
822	    }
823	  }
824	
825	  // Step 6: Post-generation analysis (pre-filter → Gravito inline → stabilize →
826	  // decide). Runs inside the governance-bypass context — mirroring invokeLLM's
827	  // own coProcessorPostGenerate call — so the internal LLM work it triggers
828	  // (prevention-layer AI evaluation, Gravito inline review) cannot recurse back
829	  // into a fully-governed pipeline (see the re-entrancy guard in
830	  // governedGenerate).
831	  const verdict = await withGovernanceBypassAsync(() =>
832	    coProcessorPostGenerate(llmResult, preSignals.signals, {
833	      skipStabilization: params.skipStabilization,
834	      callerId: params.productId,
835	    })
836	  );
837	  auditTrail.push(`[POST-GEN] Heuristics: ${verdict.postAnalysis.issues.map(i => i.type).join(', ') || 'none'}`);
838	
839	  // Step 7: Apply verdict (enforcement) — block → safe fallback message,
840	  // stabilize → fixed content, pass/regenerate → unchanged result.
841	  const enforcedResult = applyVerdict(llmResult, verdict);
842	  auditTrail.push(`[VERDICT] Decision: ${verdict.decision}, Score: ${verdict.postAnalysis.score}, Gravito ID: ${verdict.gravito_run_id}`);
843	
844	  // Step 8: Score geometry on the generated content (SHADOW MODE — observe only).
845	  // `geoResult` is the GeometryEnforcementResult OBJECT returned by enforce()
846	  // ({ passed, decision, score, promptConstraints, rewriteDirectives, auditTrail }).
847	  // In shadow mode geometry does NOT transform/gate content, so the response
848	  // `content` is the ORIGINAL generated text — NOT the enforce() object (the prior
849	  // `finalContent = geoResult` leaked that object as `content: string`) and NOT a
850	  // geometry-rewritten string (applying geoResult.decision to rewrite/block is a
851	  // later phase). selectShadowContent encodes that invariant.
852	  const generatedContent = extractContent(enforcedResult);
853	  const geoResult = enforce(generatedContent, unsafeCast(params, "boundary cast"));
854	  const finalContent = selectShadowContent(generatedContent, geoResult);
855	
856	  // Step 8 (DEEP): compose the DEEP shadow verdict from the ALREADY-COMPUTED
857	  // Step 3.5/5.5 state-vector hook results (geometryPreResult /
858	  // geometryPostResult), the shallow enforce() verdict, and the generated
859	  // content (deep-content layer v1 lives inside geometry-deep-verdict.ts).
860	  // ESCALATION-ONLY and NON-GATING: the composed verdict feeds the audit
861	  // trail, the enforcement metrics/memory, and the shadow ledger below — the
862	  // response `content` stays selectShadowContent(generatedContent, geoResult)
863	  // exactly as before. Geometry still gates NOTHING.
864	  const deepGeoResult = composeDeepGeometryVerdict(
865	    geoResult,
866	    geometryPreResult,
867	    geometryPostResult,
868	    generatedContent,
869	  );
870	  auditTrail.push(
871	    `[GEOMETRY-DEEP] Shadow verdict: ${deepGeoResult.decision} (shallow: ${geoResult.decision}, ` +
872	      `signals: ${deepGeoResult.deep.signals.map(s => s.trigger).join(', ') || 'none'}) — non-gating.`,
873	  );
874	  // Enforced-vs-passed is derived from the COMPOSED geometry verdict
875	  // (deepGeoResult.decision) — the shallow-only record predates the deep layer.
876	  if (classifyEnforcementOutcome(deepGeoResult) === 'enforced') {
877	    auditTrail.push(`[GEOMETRY] Enforcement recorded (decision: ${deepGeoResult.decision}).`);
878	  }
879	  recordGeometryEnforcement(deepGeoResult, {
880	    productId: params.productId,
881	    surfaceId: params.surfaceId,
882	    contentType: params.contentType,
883	  });
884	
885	  // SHADOW MODE — record the geometry-vs-live-verdict agreement to the canary
886	  // ledger. Fire-and-forget, flag-gated (GEOMETRY_RUNTIME_ENABLED), write-only,
887	  // and never throws into this response path. Changes NOTHING observable.
888	  // `verdict` is a CoProcessorVerdict at runtime (its `.decision` / `.gravito_run_id`
889	  // are already read below in the return); it is viewed here through the file's
890	  // existing boundary-cast helper so this shadow addition introduces no new type
891	  // errors and reads the exact same runtime values.
892	  // The ledger receives the COMPOSED deep verdict (same input contract:
893	  // decision/score fields) so the canary — and the operator-truth
894	  // geometryCanary panel reading it — surfaces the deep shadow signal.
895	  const verdictView = unsafeCast<{ decision: string; gravito_run_id?: string }>(verdict, "boundary cast");
896	  recordGeometryShadow({
897	    geometryDecision: deepGeoResult.decision,
898	    liveVerdictDecision: verdictView.decision,
899	    gravitoRunId: verdictView.gravito_run_id ?? null,
900	    geometryScore: deepGeoResult.score?.overall ?? null,
901	    surfaceType: params.surfaceId ?? null,
902	  });
903	
904	  // SHADOW-ONLY, default-OFF (GEOMETRY_EVAL_CAPTURE_ENABLED) content capture:
905	  // persist a REDACTED, adjudicable REFERENCE to the generated content at
906	  // geometry-decision time (salted hash + PII/secret-masked excerpt + signal-only
907	  // deep verdict + adjudicability metadata), NEVER raw content. Fire-and-forget,
908	  // write-only, and never throws into this response path — a byte-for-byte clone
909	  // of recordGeometryShadow's safety contract. Uses the SAME gravito_run_id as the
910	  // shadow write above → 1:1 join. MAIN PATH ONLY (the degraded path writes no
911	  // shadow row and is intentionally NOT captured). With the flag OFF this is a
912	  // no-op: zero writes, zero behavior change.
913	  recordGeometryEvalCapture({
914	    gravitoRunId: verdictView.gravito_run_id ?? null,
915	    surfaceType: params.surfaceId ?? null,
916	    productId: params.productId ?? null,
917	    content: generatedContent,
918	    liveVerdictDecision: verdictView.decision,
919	    deep: deepGeoResult,
920	    // FAIL-CLOSED gates: a row is written ONLY for an explicitly-eligible caller,
921	    // and the free-text excerpt ONLY for an explicitly excerpt-eligible caller.
922	    // No caller is flipped eligible in this packet.
923	    captureEligible: params.captureEligible === true,
924	    excerptEligible: params.excerptEligible === true,
925	    // Provenance — makes the row adjudicable (scores + structural issues) and
926	    // attributable (policy version, decision trace, actually-used model).
927	    geometryScore: deepGeoResult.score?.overall ?? null,
928	    liveVerdictScore: verdict.postAnalysis.score,
929	    policyVersion: verdict.gravitoInlineResult?.policy_version ?? null,
930	    decisionTraceId: verdict.gravitoInlineResult?.decision_trace_id ?? null,
931	    modelId: llmResult.model_used ?? llmResult.model ?? null,
932	    // Structural-only on write (description/suggestedFix dropped by the projector).
933	    liveVerdictIssues: verdict.postAnalysis.issues,
934	  });
935	
936	  // ADVISORY repeat-failure recognition — a prior-memory READ, OFF the response
937	  // hot path, immediately after the capture WRITE above and using the SAME
938	  // gravito_run_id. Recognizes when this output matches a PRIOR PERSISTED FAILING
939	  // capture row (same salted content_hash + product, prior block/regenerate) and,
940	  // on recognition, emits increment-only telemetry + a content-free log. It NEVER
941	  // alters the verdict and NEVER blocks: fire-and-forget, fail-open, and a no-op
942	  // unless GEOMETRY_EVAL_CAPTURE_ENABLED is on. Does NOT touch the return object.
943	  recognizeRepeatFailure({
944	    content: generatedContent,
945	    productId: params.productId ?? null,
946	    surfaceType: params.surfaceId ?? null,
947	    gravitoRunId: verdictView.gravito_run_id ?? null,
948	  });
949	
950	  // Step 8 (INFLUENCE): default-OFF, escalate-only geometry→verdict wiring
951	  // (packet gravito_behavior_wiring_proof_a). Behind
952	  // GEOMETRY_VERDICT_INFLUENCE_ENABLED a content-driven deep geometry `block`
953	  // ESCALATES the live verdict to `block` (via the canonical applyVerdict
954	  // safe-fallback). With the flag OFF this is a no-op: `influenced` is the exact
955	  // baseline {finalContent, verdict.decision, verdict.wasModified} and the
956	  // response below is byte-identical to today.
957	  const influenced = applyGeometryInfluence(
958	    llmResult,
959	    verdict,
960	    deepGeoResult,
961	    finalContent,
962	    auditTrail,
963	  );
964	
965	  // Step 8 (RECALL INFLUENCE): default-OFF, escalate-only recall→verdict wiring
966	  // (packet gravito_recall_wiring_proof_a) — the RECALL half of remember →
967	  // recall → prevent, chained AFTER the geometry-influence seam. Behind
968	  // GEOMETRY_RECALL_INFLUENCE_ENABLED an in-path bounded recall READ recognizes
969	  // when THIS output matches a PRIOR PERSISTED FAILING verdict (same product +
970	  // salted content_hash, prior block/regenerate) and ESCALATES the (already
971	  // geometry-influenced) verdict to `block` via the canonical applyVerdict
972	  // safe-fallback. Escalate-only, product-scoped, fail-closed (null product /
973	  // null outcome → no escalation). With the flag OFF this is a no-op: NO DB read
974	  // runs and `recallInfluenced` is the exact `influenced` baseline, so the
975	  // response below is byte-identical to today.
976	  const recallInfluenced = await applyRecallInfluence(
977	    llmResult,
978	    verdict,
979	    influenced,
980	    {
981	      content: generatedContent,
982	      productId: params.productId ?? null,
983	      surfaceType: params.surfaceId ?? null,
984	      gravitoRunId: verdictView.gravito_run_id ?? null,
985	    },
986	    auditTrail,
987	  );
988	
989	  // Step 8 (MANIFOLD INFLUENCE): default-OFF, escalate-only manifold→verdict
990	  // wiring (packet manifold_verdict_influence_proof_a) — the deep-math half of
991	  // the prevention spine, chained AFTER the recall-influence seam. Behind
992	  // MANIFOLD_VERDICT_INFLUENCE_ENABLED, when the accumulated per-session state
993	  // trajectory (from the default-OFF accumulator) classifies as a NON-DEGENERATE
994	  // UNSTABLE attractor, ESCALATE the (already content/recall-influenced) verdict
995	  // to `block` via the canonical applyVerdict safe-fallback. Escalate-only,
996	  // fail-closed (null session / degenerate trajectory → no escalation). With the
997	  // flag OFF this is a no-op: NO trajectory read runs and `manifoldInfluenced` is
998	  // the exact `recallInfluenced` baseline, so the response is byte-identical.
999	  const manifoldInfluenced = applyManifoldInfluence(
1000	    llmResult,
1001	    verdict,
1002	    recallInfluenced,
1003	    { sessionId: params.surfaceId || 'default' },
1004	    auditTrail,
1005	  );
1006	
1007	  const baseResult = {
1008	    content: manifoldInfluenced.content,
1009	    governed: true,
1010	    decision: manifoldInfluenced.decision,
1011	    modified: manifoldInfluenced.modified,
1012	    gravito_run_id: verdict.gravito_run_id,
1013	    score: verdict.postAnalysis.score,
1014	    issues: verdict.postAnalysis.issues.map(i => ({
1015	      type: i.type,
1016	      severity: i.severity,
1017	      description: i.description,
1018	    })),
1019	    auditTrail,
1020	    processingTimeMs: 0, // will be set by caller
1021	    degradedMode: false,
1022	    productRegistered: false, // will be set by caller
1023	    rawResult: llmResult,
1024	  };
1025	
1026	  // Step 9 (CANONICAL RECEIPT): default-OFF, ADDITIVE canonical verdict receipt
1027	  // (Gate→Remember→Compound→Earn-Authority) behind CANONICAL_VERDICT_RECEIPT_ENABLED.
1028	  // Flag OFF ⇒ `baseResult` is returned UNCHANGED (same reference, no
1029	  // `canonical_receipt` key) — byte-identical — and NOTHING is recorded. The
1030	  // receipt is CONTENT-FREE (a salted hash only, never raw content) and DB-FREE.
1031	  // ctx is best-effort: enforcementMode is NOT in scope here (it is computed as
1032	  // cpMode in the outer governedGenerate) ⇒ null → 'unknown'. callerId is read
1033	  // through the same widened view the control-plane gate uses
1034	  // (GovernedGenerateParams does not declare it, but runtime callers may pass
1035	  // it), falling back to productId. authenticatedTenant is the source-gated SEAM
1036	  // for tenant safety: it is the ONLY input that can promote the receipt to
1037	  // `authenticated_tenant`, and NO current caller populates it — so ctx.
1038	  // authenticatedTenant is null and derivation binds `first_party_scope`
1039	  // (productId present), BYTE-IDENTICAL to prior behavior.
1040	  const callerIdView =
1041	    (params as GovernedGenerateParams & { callerId?: string }).callerId ?? params.productId ?? null;
1042	  return attachCanonicalReceiptIfEnabled(baseResult, verdict, {
1043	    productId: params.productId ?? null,
1044	    surfaceId: params.surfaceId ?? null,
1045	    contentType: params.contentType ?? null,
1046	    contentRole: params.contentRole ?? null,
1047	    callerId: callerIdView,
1048	    authenticatedTenant: params.authenticatedTenant ?? null,
1049	    enforcementMode: null,
1050	    modelProvider: null,
1051	    modelId: llmResult.model_used ?? llmResult.model ?? null,
1052	  });
1053	}
1054	
1055	// ============================================================================
1056	// INTERNAL: Governance-Bypass Path (re-entrancy guard target)
1057	// ============================================================================
1058	
1059	/**
1060	 * Serve a governedGenerate call that arrived INSIDE the LLM governance-bypass
1061	 * context (i.e. an internal governance evaluation such as the prevention
1062	 * layer's AI check). One plain safeLLM call, no re-governing — this is what
1063	 * terminates the governedGenerate → co-processor → prevention layer →
1064	 * governedGenerate recursion.
1065	 */
1066	async function generateInternalBypass(
1067	  params: GovernedGenerateParams,
1068	): Promise<GovernedGenerateResult> {
1069	  const startTime = Date.now();
1070	  const llmResult = await safeLLM(
1071	    {
1072	      messages: buildMessages(params),
1073	      model: params.model,
1074	      max_tokens: params.max_tokens,
1075	      response_format: params.response_format,
1076	      tools: params.tools,
1077	      tool_choice: params.tool_choice,
1078	    },
1079	    { context: 'governed-generate:internal-bypass' },
1080	  );
1081	  return {
1082	    content: extractContent(llmResult),
1083	    governed: false,
1084	    decision: 'pass',
1085	    modified: false,
1086	    score: 100,
1087	    issues: [],
1088	    auditTrail: ['[BYPASS] Internal governance evaluation — recursion guard; output not re-governed'],
1089	    processingTimeMs: Date.now() - startTime,
1090	    degradedMode: false,
1091	    productRegistered: false,
1092	    rawResult: llmResult,
1093	  };
1094	}
1095	
1096	// ============================================================================
1097	// INTERNAL: Degraded Mode Pipeline
1098	// ============================================================================
1099	
1100	async function generateDegradedMode(
1101	  messages: InvokeParams['messages'],
1102	  params: GovernedGenerateParams,
1103	  auditTrail: string[],
1104	): Promise<GovernedGenerateResult> {
1105	  auditTrail.push(`[DEGRADED] Entering degraded mode pipeline.`);
1106	
1107	  // Step 1: LLM generation (no governance wrapper). safeLLM never throws —
1108	  // when every route is down it returns a structured degradation response,
1109	  // which the local policy engine below still evaluates.
1110	  const llmResult = await safeLLM(
1111	    {
1112	      messages,
1113	      model: params.model,
1114	      max_tokens: params.max_tokens,
1115	      response_format: params.response_format,
1116	      tools: params.tools,
1117	      tool_choice: params.tool_choice,
1118	    },
1119	    { context: 'governed-generate:degraded' },
1120	  );
1121	  auditTrail.push(`[DEGRADED-LLM] Raw generation complete. Tokens: ${llmResult.usage?.completion_tokens ?? 0} completion / ${llmResult.usage?.total_tokens ?? 0} total${isFallbackResponse(llmResult) ? ' (fallback response)' : ''}.`);
1122	
1123	  // Step 2: Score geometry on the degraded content (SHADOW MODE — observe only).
1124	  // Mirrors the main-path pattern: enforceDegraded() returns a
1125	  // GeometryEnforcementResult OBJECT, the response content stays the original
1126	  // generated STRING (the prior `content = enforceDegraded(...)` leaked the
1127	  // object as `content: string` — sibling of the shipped main-path fix).
1128	  const degradedContent = extractContent(llmResult);
1129	  const geoResult = enforceDegraded(degradedContent, unsafeCast(params, "boundary cast"));
1130	  const content = selectShadowContent(degradedContent, geoResult);
1131	  if (classifyEnforcementOutcome(geoResult) === 'enforced') {
1132	    auditTrail.push(`[DEGRADED-GEOMETRY] Enforcement recorded (decision: ${geoResult.decision}).`);
1133	  }
1134	  recordGeometryEnforcement(geoResult, {
1135	    productId: params.productId,
1136	    surfaceId: params.surfaceId,
1137	    contentType: params.contentType,
1138	    degradedMode: true,
1139	  });
1140	
1141	  // Step 3: Evaluate with local policy engine
1142	  const policyResult = evaluateDegradedPolicy({
1143	    content,
1144	    contentType: params.contentType || 'general',
1145	    surfaceId: params.surfaceId,
1146	    productId: params.productId,
1147	    contentRole: params.contentRole,
1148	    audienceType: params.audienceType,
1149	  });
1150	  auditTrail.push(`[DEGRADED-POLICY] Decision: ${policyResult.decision}, Score: ${policyResult.score}`);
1151	
1152	  // Step 4: Record evaluation for later analysis (hash the CONTENT STRING for
1153	  // the audit trail — the old call hashed the geometry object).
1154	  auditTrail.push(`[DEGRADED-RECORD] contentHash: ${createHash('sha256').update(content).digest('hex').slice(0, 16)}…`);
1155	  recordDegradedEvaluation(policyResult);
1156	
1157	  // Step 5: Build final result
1158	  return {
1159	    content: policyResult.modifiedContent,
1160	    governed: true, // It was governed, just by a degraded system
1161	    decision: policyResult.decision,
1162	    modified: policyResult.modifications.length > 0,
1163	    score: policyResult.score,
1164	    issues: policyResult.issues.map(i => ({
1165	      type: i.type,
1166	      severity: i.severity,
1167	      description: i.description,
1168	    })),
1169	    auditTrail,
1170	    processingTimeMs: 0,
1171	    degradedMode: true,
1172	    productRegistered: false,
1173	    rawResult: llmResult,
1174	  };
1175	}
1176	
1177	// ============================================================================
1178	// HELPERS
1179	// ============================================================================
1180	
1181	/**
1182	 * Map a geometry-runtime stateSnapshot (flat Record<string, number>) onto the
1183	 * CanonicalEmotionalState the advanced neurocosmology hooks expect. Only the
1184	 * base dimensions that exist in the canonical shape are mapped; derived
1185	 * dimensions are recomputed by updateBaseDimensions.
1186	 */
1187	function buildCanonicalState(
1188	  snapshot: Record<string, number> | undefined,
1189	  sessionId: string,
1190	  userId: string,
1191	): CanonicalEmotionalState {
1192	  return updateBaseDimensions(createInitialState(sessionId, userId), {
1193	    emotionalMass: snapshot?.emotionalMass ?? 0,
1194	    valenceCharge: snapshot?.emotionalValence ?? snapshot?.emotionalCharge ?? 0,
1195	    attentionCurvature: snapshot?.attentionCurvature ?? 0,
1196	    memoryEntropy: snapshot?.memoryEntropy ?? 0.5,
1197	    relationalDistance: snapshot?.emotionalDistance ?? 1,
1198	  });
1199	}
1200	
1201	function buildMessages(params: GovernedGenerateParams, contextInjection?: string): InvokeParams['messages'] {
1202	  const messages: Message[] = [];
1203	
1204	  // Add system prompt if provided
1205	  if (params.systemPrompt) {
1206	    messages.push({ role: 'system', content: params.systemPrompt });
1207	  }
1208	
1209	  // Add product-aware governance context injection (from resolveGovernanceContext)
1210	  const governanceContext = contextInjection || buildGovernanceContextString(params);
1211	  if (governanceContext) {
1212	    const existingSystem = messages.find((m) => m.role === 'system');
1213	    if (existingSystem) {
1214	      existingSystem.content = governanceContext + '\n\n' + existingSystem.content;
1215	    } else {
1216	      messages.push({ role: 'system', content: governanceContext });
1217	    }
1218	  }
1219	
1220	  // Add the actual messages
1221	  if (params.messages) {
1222	    for (const msg of params.messages) {
1223	      // Skip system messages if we already injected one
1224	      if (msg.role === 'system' && messages.some(m => m.role === 'system')) {
1225	        const systemMsg = messages.find(m => m.role === 'system');
1226	        if (systemMsg) {
1227	          systemMsg.content += '\n\n' + (typeof msg.content === 'string' ? msg.content : '');
1228	        }
1229	      } else {
1230	        messages.push(msg);
1231	      }
1232	    }
1233	  }
1234	
1235	  return messages;
1236	}
1237	
1238	function buildGovernanceContextString(params: GovernedGenerateParams): string {
1239	  const parts: string[] = [];
1240	
1241	  if (params.contentRole === 'user-facing') {
1242	    parts.push('[GOVERNANCE] This content is user-facing. Apply full governance checks.');
1243	  }
1244	  if (params.audienceType === 'medical') {
1245	    parts.push('[GOVERNANCE] Medical content — include appropriate disclaimers. Do not provide medical advice.');
1246	  }
1247	  if (params.audienceType === 'legal') {
1248	    parts.push('[GOVERNANCE] Legal content — include appropriate disclaimers. Do not provide legal advice.');
1249	  }
1250	  if (params.contentType === 'marketing') {
1251	    parts.push('[GOVERNANCE] Marketing content — avoid misleading claims. Be factual and verifiable.');
1252	  }
1253	
1254	  return parts.length > 0 ? parts.join('\n') : '';
1255	}
1256	
1257	function extractContent(result: InvokeResult): string {
1258	  const content = result?.choices?.[0]?.message?.content;
1259	  if (!content) return '';
1260	  return typeof content === 'string' ? content : JSON.stringify(content);
1261	}
1262	
1263	function updateMetrics(
1264	  result: GovernedGenerateResult,
1265	  productKey: string,
1266	  startTime: number,
1267	): void {
1268	  const latency = Date.now() - startTime;
1269	  _metrics.avgLatencyMs = ((_metrics.avgLatencyMs * (_metrics.totalCalls - 1)) + latency) / _metrics.totalCalls;
1270	
1271	  switch (result.decision) {
1272	    case 'pass': _metrics.totalPassed++; break;
1273	    case 'stabilize': _metrics.totalStabilized++; break;
1274	    case 'block':
1275	      _metrics.totalBlocked++;
1276	      _metrics.byProduct[productKey].blocked++;
1277	      break;
1278	    case 'regenerate': _metrics.totalRegenerated++; break;
1279	  }
1280	}
1281	
1282	/**
1283	 * Reset metrics (for testing).
1284	 */
1285	export function resetGovernedGenerateMetrics(): void {
1286	  _metrics.totalCalls = 0;
1287	  _metrics.totalPassed = 0;
1288	  _metrics.totalStabilized = 0;
1289	  _metrics.totalBlocked = 0;
1290	  _metrics.totalRegenerated = 0;
1291	  _metrics.totalDegraded = 0;
1292	  _metrics.totalErrors = 0;
1293	  _metrics.avgLatencyMs = 0;
1294	  _metrics.byProduct = {};
1295	}
